define('theme_material/displaymenu', [], function() {
    var storageKey = 'theme_material_display_menu_language';

    function select(menu, name, value) {
        menu.querySelectorAll('[data-setting="' + name + '"]').forEach(function(option) {
            var active = option.dataset.value === value;
            option.setAttribute(name === 'colour' ? 'aria-checked' : 'aria-pressed', String(active));
            if (name === 'colour') {
                option.tabIndex = active ? 0 : -1;
            }
        });
    }

    function language(menu, value) {
        menu.dataset.panelLanguage = ['en', 'yue', 'bi'].includes(value) ? value : 'en';
        select(menu, 'language', menu.dataset.panelLanguage);
    }

    async function saveMotion(menu, value) {
        if (menu.dataset.saving) {
            return;
        }
        menu.dataset.saving = 'true';
        var status = menu.querySelector('[data-panel-status]');
        status.textContent = '';
        try {
            var response = await fetch(menu.dataset.motionUrl, {
                method: 'POST',
                body: new URLSearchParams({motion: value, sesskey: M.cfg.sesskey}),
            });
            var data = await response.json();
            if (!response.ok || !['expressive', 'calm', 'off'].includes(data.motion)) {
                throw new Error('Motion was not saved');
            }
            document.documentElement.dataset.mdMotion = data.motion;
            document.dispatchEvent(new Event('theme-material-motion-change'));
            select(menu, 'motion', data.motion);
        } catch (err) {
            status.textContent = menu.dataset.saveFailure;
        } finally {
            delete menu.dataset.saving;
        }
    }

    return {init: function() {
        var menu = document.querySelector('.mm-display');
        if (!menu || menu.dataset.initialised) {
            return;
        }
        menu.dataset.initialised = 'true';
        var toggle = menu.querySelector('[data-bs-toggle="dropdown"]');
        var panel = menu.querySelector('.mm-display-panel');
        document.addEventListener('keydown', function(e) {
            if (!panel.classList.contains('show')) {
                return;
            }
            if (e.key === 'Escape' && (menu.contains(e.target) || e.target === document.body)) {
                e.preventDefault();
                e.stopPropagation();
                toggle.click();
                toggle.focus();
                return;
            }
            if (e.target.matches('[data-setting="colour"]') &&
                    ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'].includes(e.key)) {
                e.preventDefault();
                e.stopPropagation();
                var choices = Array.from(menu.querySelectorAll('[data-setting="colour"]:enabled'));
                var step = ['ArrowLeft', 'ArrowUp'].includes(e.key) ? -1 : 1;
                var next = choices[(choices.indexOf(e.target) + step + choices.length) % choices.length];
                next.focus();
                next.click();
            }
        }, true);
        try {
            language(menu, localStorage.getItem(storageKey));
        } catch (err) {
            language(menu, 'en');
        }
        menu.addEventListener('click', function(e) {
            var option = e.target.closest('[data-setting]');
            if (!option || option.disabled) {
                return;
            }
            var value = option.dataset.value;
            switch (option.dataset.setting) {
                case 'colour':
                    select(menu, 'colour', value);
                    break;
                case 'motion':
                    saveMotion(menu, value);
                    break;
                case 'language':
                    language(menu, value);
                    try {
                        localStorage.setItem(storageKey, value);
                    } catch (err) {
                        // Keep the selection for this page when storage is unavailable.
                    }
                    break;
            }
        });
    }};
});
